"""Log in over plain HTTP and dump what comes next: text, forms, links, scripts."""
import json, re, sys, time
from html.parser import HTMLParser
from urllib.parse import urljoin
import httpx2 as httpx

env = open(sys.argv[1]).read()
access = {s["siteId"]: s for s in json.loads(re.search(r"CHALLENGE_SITE_ACCESS='(.*)'", env).group(1))}
UA = {"User-Agent": "error404-probe/1.0"}


class Forms(HTMLParser):
    def __init__(self):
        super().__init__()
        self.forms, self.links, self.scripts, self.text, self._skip = [], [], [], [], 0

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "form":
            self.forms.append({"action": a.get("action"), "method": a.get("method"), "inputs": []})
        elif tag in ("input", "button", "select", "textarea") and self.forms:
            self.forms[-1]["inputs"].append((tag, a.get("name"), a.get("type"), (a.get("value") or "")[:40]))
        elif tag == "a" and a.get("href"):
            self.links.append(a["href"])
        elif tag == "script":
            self.scripts.append(a.get("src") or "inline")
            self._skip += 1
        elif tag == "style":
            self._skip += 1

    def handle_endtag(self, tag):
        if tag in ("script", "style") and self._skip:
            self._skip -= 1

    def handle_data(self, d):
        if not self._skip and d.strip():
            self.text.append(d.strip())


def dump(r, n=1500):
    p = Forms()
    p.feed(r.text)
    print(f"--- {r.status_code} {r.url} hist={[h.status_code for h in r.history]} len={len(r.text)}")
    print("TEXT:", " | ".join(p.text)[:n])
    print("FORMS:", p.forms)
    print("LINKS:", p.links[:60])
    print("SCRIPTS:", p.scripts)
    return p


def login(site):
    s = access[site]
    c = httpx.Client(headers=UA, follow_redirects=True, timeout=30)
    r = c.get(s["url"] + "/")
    p = Forms()
    p.feed(r.text)
    form = p.forms[0]
    data = {name: value for tag, name, typ, value in form["inputs"] if name and typ == "hidden"}
    m = re.search(r'name="csrf" value="([^"]+)"', r.text)
    if m:
        data["csrf"] = m.group(1)
    data["username"] = s["credentials"]["username"]
    data["password"] = s["credentials"]["password"]
    t = time.monotonic()
    r = c.post(urljoin(str(r.url), form["action"]), data=data)
    print(f"login post {time.monotonic() - t:.2f}s")
    return c, r


if __name__ == "__main__":
    site = sys.argv[2]
    c, r = login(site)
    dump(r, 3000)
    for path in sys.argv[3:]:
        t = time.monotonic()
        r = c.get(urljoin(access[site]["url"], path))
        print(f"GET {path} {time.monotonic() - t:.2f}s")
        dump(r, 3000)

